import React, { useEffect, useState } from "react";
import { BrowserRouter as Router, Route, Switch, useLocation as useRouterLocation } from "react-router-dom";  // Renamed useLocation
import { Offline } from "react-detect-offline";
import Hero from "../home/Hero";
import Login from "../logIn/Login";
import Signup from "../signUp/Signup";
import Navbar from "../navbar";
import ProtectedRoute from "../protectedRoute/ProtectedRoute";
import TeacherDashboard from "../Teacher/Dashboard/Dashboard";
import StudentDashboard from "../dashboard/Dashboard";
import { Roles } from "../Roles/roles";

function App(props) {
  const [count, setCount] = useState(1);

  const handleOffline = () => {
    setCount(count + 1);
    if (count % 2 === 0) {
      message.success("Connected to internet");
    } else {
      message.error("Please connect to internet");
    }
  };

  useEffect(() => {
    window.addEventListener("contextmenu", (e) => {
      e.preventDefault();
    });
    window.addEventListener("keydown", (e) => {
      if (e.key === "F12") {
        e.preventDefault();
      }
    });
  }, []);

  const role = props.userInfo?.role; // Ensure role is extracted from props correctly
  const currentLocation = useRouterLocation(); // Renamed 'location' to 'currentLocation'

  return (
    <div className={count % 2 ? "" : " pointer__select__none"}>
      <Offline onChange={(e) => handleOffline(e)}></Offline>

      <Router>
        {/* Conditionally render Navbar only if the current route is not the home ("/") route */}
        {currentLocation.pathname !== "/" && <Navbar />}

        <Switch>
          <Route exact path="/" component={() => <Hero id="home" />} />
          <Route exact path="/signup" component={Signup} />
          <Route exact path="/signin" component={Login} />
          <ProtectedRoute
            exact
            path="/home"
            component={
              Roles.teacher === role ? TeacherDashboard : StudentDashboard
            }
          />
          <ProtectedRoute
            exact
            path="/attempt-test"
            component={AttemptTest}
          />
          <ProtectedRoute
            exact
            path="/create-test"
            component={Roles.teacher === role ? CreateTest : AttemptTest}
          />
          <ProtectedRoute exact path="/result" component={Result} />
          <ProtectedRoute
            exact
            path={`/result/${selectedTestName}`}
            component={IndividualResult}
          />
          <ProtectedRoute
            exact
            path="/test-instructions"
            component={TestInstruction}
          />
          <ProtectedRoute
            exact
            path="/start-test"
            component={TestPreviewWrapper}
          />
          <ProtectedRoute exact path="/profile" component={Profile} />
          <ProtectedRoute
            exact
            path="/assigned-test"
            component={
              Roles.teacher === role ? AssignedTestsWrapper : StudentDashboard
            }
          />
          <ProtectedRoute
            exact
            path={`/test-status/${selectedAssignedTestName}`}
            component={TestStatus}
          />
          <ProtectedRoute component={Login} />
        </Switch>
       
      </Router>
    </div>
  );
}

const mapStateToProps = (state) => {
  return {
    selectedTestName: state.selectedTest.selectedTestResultData.testName
      ?.replace(/\s+/g, "-")
      .toLowerCase(),
    userInfo: state.auth.user,
    selectedAssignedTestName: state.selectedTest.selectedAssignedTestData.testName
      ?.replace(/\s+/g, "-")
      .toLowerCase(),
  };
};

export default connect(mapStateToProps, null)(App);
